import subprocess, json, sys

skill_dir = "/workspace/skills/state-customer-support"

def cli(tool, args, user="user_1d80ab67"):
    cmd = ["python", "cli.py", "call", tool, "--user", user, "--args", json.dumps(args)]
    r = subprocess.run(cmd, cwd=skill_dir, capture_output=True, text=True)
    out = r.stdout.strip()
    if r.stderr:
        print(f"STDERR ({tool}): {r.stderr[:300]}")
    if not out:
        print(f"EMPTY OUTPUT for {tool}")
        return None
    try:
        return json.loads(out)
    except json.JSONDecodeError:
        print(f"JSON PARSE ERROR for {tool}: {out[:300]}")
        return None

